import React, {useEffect} from 'react';
import icons from '../site/icons';
import getKey from './KeyGenerator';
import validate from './validate';

const EditableTextField = ({

    title,
    data,
    toggle,
    edit,
    setEdited,
    edited

}) => {

    useEffect(() => {
        setEdited(data !== null && data !== undefined ? data : '');
    }, [data]);

    const ifUndefinedString = (value) => {
        //console.log(`ifUndefinedString => value: ${value}`);
        //let newValue = (value === undefined) ? 'empty...' : value;
        let newValue = (validate(value) === null) ? 'empty...' : value;
        newValue = (value === null) ? 'empty...' : value;
        //console.log(`ifUndefinedString => newValue: ${newValue}`);
        return newValue;
    }

    return <div>
                {
                    (!title)
                    ? null
                    : <div className='flexContainer containerDetail bg-lite centerVertical'>
                        <div className='containerDetail flex2Column color-yellow size20 p-20'>
                            {title}
                        </div>
                        <div className='flexColumn contentRight'>
                            <div
                                className={`button`}
                                onClick={() => toggle()}
                            >
                                {
                                    (edit)
                                    ? <div className='r-10 p-20 bg-lite color-neogreen bold centeredContent ht-60'>
                                        save
                                    </div>
                                    : <div className='r-10 p-20 bg-lite ht-60 centeredContent'>
                                        {icons.edit}
                                    </div>
                                }
                            </div>
                        </div>
                    </div>
                }
                <div className='containerDetail'>
                    <div className='color-soft button'>
                    {
                        (edit)
                        ? <textarea
                            className="inputField size20 r-10 height-200"
                            onChange={e => setEdited(e.target.value || edited || data || '')}
                            onBlur={toggle}
                            /*
                            value={
                                edited !== null && edited !== undefined
                                    ? edited
                                    : (data !== null && data !== undefined ? data : '')
                            }
                            */
                            value={edited || data || ''}
                            //placeholder={ifUndefinedString(data)}
                            placeholder={edited || ifUndefinedString(data) || 'Enter your journal...'}
                        />
                        : <div 
                            onClick={() => {
                                setEdited(data !== null && data !== undefined ? data : '');
                                toggle();
                            
                            }}
                            className='height-400'
                        > 
                            {
                                (ifUndefinedString(data))
                                    ? ifUndefinedString(data).split('\n').map((line, index) => (
                                        <div key={getKey(`data${index}`)} className='containerDetail p-20 mb-5'>
                                            {line}
                                            <br />
                                        </div>
                                    ))
                                    : null
                            }
                        </div>
                    }
                    </div>
                </div>
            </div>
}
export default EditableTextField;